APP_CSS = r"""
<style>
@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.css');
:root{--bg:#f8fbff;--navy:#10294b;--text:#28486e;--muted:#6b7f98;--line:#d8e4f1;--blue:#1677f2;--blue2:#0a66d8;--green:#0aa35e;--orange:#f97316;--red:#ef3038}
html,body,[class*="css"]{font-family:'Pretendard',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;letter-spacing:-.015em}
#MainMenu,footer{visibility:hidden!important}
header[data-testid="stHeader"]{background:transparent;pointer-events:none}
header[data-testid="stHeader"] button{pointer-events:auto}
[data-testid="stToolbarActions"],[data-testid="stDecoration"]{display:none}
[data-testid="stExpandSidebarButton"],[data-testid="stSidebarCollapseButton"],[data-testid="stSidebar"] button[kind="headerNoPadding"]{display:none}
.stApp{background:linear-gradient(180deg,#ffffff 0%,#f8fbff 100%);color:var(--navy)}
.block-container{max-width:1580px;padding:1rem 1.4rem 1.7rem!important}
/* Shared, always visible navigation; reporting controls live in the content. */
[data-testid="stSidebar"]{display:flex!important;visibility:visible!important;transform:none!important;margin-left:0!important;width:236px!important;min-width:236px!important;max-width:236px!important;background:#f2f7fd!important;border-right:1px solid var(--line)}
[data-testid="stSidebarHeader"]{display:none}
[data-testid="stSidebarContent"]{padding:24px 12px}
[data-testid="stSidebarUserContent"]{padding:0!important}
.sidebar-brand{font-size:21px;font-weight:850;color:var(--navy);margin:0 0 22px}.side-section{font-size:13px;font-weight:700;color:#617a99;margin:12px 0 10px}
[data-testid="stSidebar"] [role="radiogroup"]{gap:10px}[data-testid="stSidebar"] [role="radiogroup"] label{padding:12px 10px;background:transparent;border:1px solid transparent;border-radius:9px;margin:0;width:100%}[data-testid="stSidebar"] [role="radiogroup"] label:has(input:checked){background:#1677f2;color:#fff;border-color:#1677f2}[data-testid="stSidebar"] [role="radiogroup"] label p{font-size:13px;font-weight:650}[data-testid="stSidebar"] [role="radiogroup"] label:has(input:checked) p{color:#fff}
.developer-note{font-size:12px;line-height:1.65;color:#617a99;padding:14px 10px;border:1px solid #d9e4f0;border-radius:9px;background:#fff}.developer-note b{color:#315579}.st-key-global_release button{font-size:14px;color:#496789;border-color:#cddcec}
@media(max-width:800px){[data-testid="stAppViewContainer"]{flex-direction:column;overflow:auto}[data-testid="stSidebar"]{position:relative!important;width:100%!important;min-width:0!important;max-width:none!important;height:auto!important;max-height:none!important;border-right:0;border-bottom:1px solid #d9e4f0}[data-testid="stSidebarContent"]{padding:12px!important;overflow:visible}[data-testid="stSidebarUserContent"]{padding:0!important}[data-testid="stSidebar"] [role="radiogroup"]{flex-direction:row;flex-wrap:wrap}.sidebar-brand{margin:0 0 8px}[data-testid="stMain"]{overflow:visible;min-height:0}}

/* existing output and mode2 compatibility */
.app-head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin:0 0 16px;padding:0 0 15px;border-bottom:1px solid var(--line)}.app-brand{display:flex;gap:11px;align-items:center}.app-logo{width:38px;height:38px;border-radius:9px;background:#0f2747;display:flex;align-items:center;justify-content:center;color:#fff;font-size:17px;font-weight:800}.app-title{font-size:1.35rem;font-weight:800;color:#10294b}.app-sub{font-size:.79rem;color:#60728c;margin-top:2px}.live-chip{background:#eef6ff;border:1px solid #cfe3ff;border-radius:9px;padding:7px 11px;font-size:.73rem;color:#1769c2;white-space:nowrap}
.section-title{font-size:1rem;font-weight:800;color:#10294b;margin:15px 0 8px}.section-title:after{content:"";display:inline-block;width:4px;height:4px;background:#8ca0b8;border-radius:50%;margin:0 0 2px 7px}.compact-title{margin-top:11px!important}.card-title{font-size:.9rem;font-weight:750;color:#183354}.card-desc{font-size:.76rem;color:#6b7e95;line-height:1.45}.work-card,.download-card,.mode-banner,.empty-card,.info-panel,.region-card{background:#fff;border:1px solid var(--line);border-radius:9px}.work-card{padding:12px 13px;margin-bottom:9px}.work-title{font-size:.87rem;font-weight:700;color:#183354}.work-desc{font-size:.75rem;color:#6b7e95;line-height:1.5}.download-card{display:flex;gap:9px;align-items:flex-start;padding:11px 12px;margin-bottom:6px;min-height:66px}.download-icon{width:32px;height:32px;flex:0 0 32px;border-radius:7px;background:#eef6ff;display:flex;align-items:center;justify-content:center;color:#1677f2}.info-panel{display:flex;gap:9px;padding:11px 12px;min-height:74px}.info-icon{width:29px;height:29px;flex:0 0 29px;border-radius:7px;background:#eef6ff;color:#1677f2;display:flex;align-items:center;justify-content:center;font-weight:700}.mode-banner{padding:12px 14px;margin-bottom:10px}.mode-eyebrow{font-size:.69rem;color:#718198;font-weight:700}.mode-title{font-size:1rem;color:#183354;font-weight:750}.mode-desc{font-size:.75rem;color:#718198;margin-top:3px}.region-card{padding:12px 14px;margin-top:9px}.region-track{height:7px;background:#edf2f7;border-radius:999px;overflow:hidden;display:flex;margin:9px 0}.region-seg-1{background:#1677f2}.region-seg-2{background:#7aaeea}.region-seg-3{background:#d5e5f7}.region-legend{display:flex;gap:16px;flex-wrap:wrap;font-size:.71rem;color:#718198}.kpi-row{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin:9px 0 12px}.kpi-card{background:#fff;border:1px solid var(--line);border-radius:8px;padding:13px 14px}.kpi-label{font-size:.71rem;color:#71717a;font-weight:600}.kpi-value{font-size:1.5rem;font-weight:750;color:#10294b}.kpi-unit{font-size:.75rem;color:#71717a;margin-left:2px}.kpi-note{font-size:.7rem;color:#8d9aad;margin-top:5px}
.waiting-card{max-width:460px;margin:60px auto;background:#fff;border:1px solid var(--line);border-radius:11px;text-align:center;padding:28px}.waiting-title{font-size:1rem;font-weight:750;color:#183354;margin:7px 0 4px}.waiting-desc,.waiting-meta{font-size:.76rem;color:#718198}
[data-testid="stAlert"]{padding:.58rem .72rem!important;font-size:.77rem!important;margin:.35rem 0!important;border-radius:8px!important}[data-testid="stDataFrame"],[data-testid="stDataEditor"]{font-size:.76rem!important;border:1px solid var(--line)!important;border-radius:9px!important;overflow:hidden!important}[data-testid="stExpander"]{border:1px solid var(--line)!important;border-radius:10px!important;background:#fff!important}

</style>
"""
